from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    constraints = {}
    required = set()
    for name, interval in data["roots"].items():
        required.add(name)
        constraints.setdefault(name, []).append(tuple(interval))

    best_vector = None
    best_versions = None

    def within(version, ranges):
        return all(low <= version <= high for low, high in ranges)

    def has_cycle(graph):
        visiting = set()
        visited = set()

        def visit(node):
            if node in visiting:
                return True
            if node in visited:
                return False
            visiting.add(node)
            for target in graph.get(node, ()):
                if visit(target):
                    return True
            visiting.remove(node)
            visited.add(node)
            return False

        return any(visit(node) for node in graph)

    def search(assigned, needed, ranges, graph):
        nonlocal best_vector, best_versions

        pending = needed - assigned.keys()
        if not pending:
            vector = tuple(assigned[name]["version"] if name in assigned else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"] for name, row in assigned.items()}
            return

        name = min(pending)
        allowed = ranges.get(name, [])
        forbidden = blocked.get(name, ())
        pin = pins.get(name)
        rows = sorted(packages.get(name, ()), key=lambda row: row["version"], reverse=True)

        for row in rows:
            version = row["version"]
            if not within(version, allowed):
                continue
            if version in forbidden or (pin is not None and version != pin):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_needed = set(needed)
            next_ranges = {key: list(value) for key, value in ranges.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            edges = []
            valid = True

            for dep in row.get("deps", ()):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                bound = (dep["min"], dep["max"])
                next_needed.add(target)
                next_ranges.setdefault(target, []).append(bound)
                if target in next_assigned and not within(next_assigned[target]["version"], next_ranges[target]):
                    valid = False
                    break
                edges.append(target)

            if not valid:
                continue
            next_graph[name] = edges
            if has_cycle(next_graph):
                continue
            search(next_assigned, next_needed, next_ranges, next_graph)

    search({}, required, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
